import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { consoleI18n } from "../i18n/i18n";
import { ConsoleApplication } from "./ConsoleApplication";

const authenticatedSession = {
  kind: "authenticated" as const,
  context: {
    attentionCount: 0,
    locale: "en-US",
    session: {
      kind: "authenticated" as const,
      principalName: "Avery Chen",
      scope: { id: "scope-platform", name: "Platform Engineering" },
    },
  },
};

describe("ConsoleApplication", () => {
  beforeEach(async () => {
    await consoleI18n.changeLanguage("en-US");
  });

  afterEach(() => {
    cleanup();
  });

  it("persists an authenticated language selection before applying it to the Console", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue(authenticatedSession),
      saveConsoleLocale: vi.fn().mockResolvedValue(true),
    };

    render(<ConsoleApplication sessionAdapter={sessionAdapter} />);

    await screen.findByRole("banner");
    fireEvent.click(screen.getByRole("radio", { name: "中文" }));

    await waitFor(() => expect(sessionAdapter.saveConsoleLocale).toHaveBeenCalledWith("zh-CN"));
    await waitFor(() => expect(document.documentElement.lang).toBe("zh-CN"));
  });

  it("keeps the current language when the authenticated preference cannot be saved", async () => {
    const sessionAdapter = {
      readConsoleSession: vi.fn().mockResolvedValue(authenticatedSession),
      saveConsoleLocale: vi.fn().mockResolvedValue(false),
    };

    render(<ConsoleApplication sessionAdapter={sessionAdapter} />);

    await screen.findByRole("banner");
    fireEvent.click(screen.getByRole("radio", { name: "中文" }));

    await waitFor(() => expect(sessionAdapter.saveConsoleLocale).toHaveBeenCalledWith("zh-CN"));
    expect(document.documentElement.lang).toBe("en-US");
  });
});

