import { expect, test, type Page } from "@playwright/test";

async function expectUnavailableSession(page: Page) {
  await expect(page.getByRole("heading", { name: "Console temporarily unavailable" })).toBeVisible();
  await expect(page.getByRole("link", { name: "Sign in" })).not.toBeVisible();
}

test("console-shell presents an accessible login handoff", async ({ page }) => {
  const pageErrors: string[] = [];
  page.on("pageerror", (error) => pageErrors.push(error.message));

  await page.addInitScript(() => localStorage.setItem("oac.console.locale", "en-US"));
  await page.route("**/api/console/session", (route) => route.fulfill({ status: 401 }));
  await page.goto("/");

  expect(pageErrors).toEqual([]);
  await expect(page.locator("main")).toBeVisible();
  await expect(page.getByRole("heading", { name: "Open Agent Cluster Console" })).toBeVisible();
  await expect(page.getByText("Sign in to continue to your authorized workspace.")).toBeVisible();
  await expect(page.getByRole("link", { name: "Sign in" })).toHaveAttribute("href", "/login");
  await expect(page.getByRole("button", { name: "English" })).toHaveAttribute("aria-pressed", "true");

  await page.getByRole("link", { name: "Sign in" }).click();

  await expect(page).toHaveURL(/\/login$/);
  await expect(page.getByRole("heading", { name: "Sign in" })).toBeVisible();
  await expect(page.getByRole("link", { name: "Back to Console" })).toHaveAttribute("href", "/");
});

test("console-shell keeps a server session failure distinct from anonymous access", async ({ page }) => {
  await page.route("**/api/console/session", (route) => route.fulfill({ status: 500 }));
  await page.goto("/");

  await expectUnavailableSession(page);
});

test("console-shell keeps a malformed session response distinct from anonymous access", async ({ page }) => {
  await page.route("**/api/console/session", (route) => route.fulfill({
    contentType: "application/json",
    body: "{not-json}",
  }));
  await page.goto("/");

  await expectUnavailableSession(page);
});

